<p>Automated call consent: <strong><?=htmlspecialchars(ucfirst(str_replace('_',' ',$callConsent['consent_status'])),ENT_QUOTES,'UTF-8')?></strong><?php if($callConsent['consented_at']): ?> · recorded <?=htmlspecialchars($callConsent['consented_at'],ENT_QUOTES,'UTF-8')?><?php endif;?></p>
