<?php if(in_array($role,[1,2,3],true)&&$callConsent['consent_status']==='granted'&&trim((string)$mother['phone'])!==''): ?>
<hr><form id="mcare-outbound-start" class="form-inline"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['csrf_token'])?>"><input type="hidden" name="mother_id" value="<?=$id?>"><div class="form-group"><label class="sr-only" for="mcare-call-purpose">Purpose</label><select id="mcare-call-purpose" class="form-control" name="purpose"><option value="test">Authorized test call</option><option value="anc_followup">ANC follow-up</option><option value="appointment_reminder">Appointment reminder</option><option value="postnatal_followup">Postnatal follow-up</option><option value="missed_appointment">Missed appointment</option><option value="medication_reminder">Medication reminder</option><option value="worker_followup">Care-team follow-up</option></select></div> <label for="mcare-call-priority">Queue priority</label> <select id="mcare-call-priority" class="form-control" name="priority"><option value="5">Normal</option><option value="3">High</option><option value="1">Highest</option></select> <label for="mcare-call-schedule">Schedule (optional)</label> <input id="mcare-call-schedule" class="form-control" type="datetime-local" name="scheduled_at"> <button class="btn btn-primary" type="submit"><i class="fa fa-phone"></i> Call / schedule</button> <a class="btn btn-default" href="outbound_calls">Call monitoring</a></form>
<div id="mcare-outbound-feedback" class="mcare-muted" aria-live="polite">Calls use the configured Asterisk trunk and are subject to consent, calling hours, provider availability, and call limits.</div>
<div class="table-responsive"><table class="table table-condensed"><thead><tr><th>Purpose</th><th>Status</th><th>Started</th><th>Duration</th><th>Action</th></tr></thead><tbody id="mcare-outbound-history"><tr><td colspan="5">Loading call history…</td></tr></tbody></table></div>
<script>
(function(){const api='outbound_call_api.php',mother=<?=$id?>,csrf=<?=json_encode($_SESSION['csrf_token'])?>,body=document.getElementById('mcare-outbound-history'),feedback=document.getElementById('mcare-outbound-feedback');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function refresh(){try{const r=await fetch(api+'?action=history&mother_id='+mother,{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'History unavailable');body.innerHTML=d.calls.map(c=>`<tr><td>${esc(c.purpose)}</td><td>${esc(c.status)}${c.scheduled_at?' · '+esc(c.scheduled_at):''}</td><td>${esc(c.started_at||c.created_at)}</td><td>${esc(c.duration_seconds??'—')}</td><td>${['queued','initiating','ringing','answered','in_progress'].includes(c.status)?`<button type="button" class="btn btn-xs btn-danger mcare-call-cancel" data-id="${esc(c.call_id)}">Cancel</button>`:['busy','no_answer','failed'].includes(c.status)&&Number(c.retry_count)<2?`<button type="button" class="btn btn-xs btn-warning mcare-call-retry" data-id="${esc(c.call_id)}">Retry</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5">No outbound calls.</td></tr>';}catch(e){body.innerHTML='<tr><td colspan="5">Call history is unavailable.</td></tr>';}}document.getElementById('mcare-outbound-start').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;feedback.textContent='Sending call request to Asterisk…';try{const f=new FormData(e.currentTarget);f.append('action','start');const r=await fetch(api,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(f)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Call request failed');feedback.textContent=d.message;await refresh();}catch(x){feedback.textContent=x.message;}finally{b.disabled=false;}});body.addEventListener('click',async e=>{const b=e.target.closest('.mcare-call-cancel,.mcare-call-retry');if(!b)return;b.disabled=true;try{const f=new URLSearchParams({_csrf:csrf,action:'cancel',call_id:b.dataset.id});if(b.classList.contains('mcare-call-retry')){const form=new FormData(document.getElementById('mcare-outbound-start'));for(const [k,v] of form.entries())f.set(k,v);f.set('action','start');f.set('retry_of',b.dataset.id);}const r=await fetch(api,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:f}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Call action failed');feedback.textContent=d.message;await refresh();}catch(x){feedback.textContent=x.message;}finally{b.disabled=false;}});refresh();window.setInterval(refresh,7000);})();
</script>
<?php elseif(in_array($role,[1,2,3],true)): ?><p>A valid phone number and recorded automated-call consent are required to place calls.</p><?php endif;?>
